// Получаем параметры из webhook
const startDate = new Date($input.first().json.startDate);
const endDate = new Date($input.first().json.endDate);
const duration = 30; // Длительность слота в минутах
const workStart = 9; // Начало рабочего дня (9:00)
const workEnd = 18; // Конец рабочего дня (18:00)
const minLeadTime = 24; // Минимум за 24 часа

// Получаем занятые события из Google Calendar
const busyEvents = $input.all().map(item => ({
  start: new Date(item.json.start.dateTime || item.json.start.date),
  end: new Date(item.json.end.dateTime || item.json.end.date)
}));

// Функция проверки, занят ли слот
function isSlotBusy(slotStart, slotEnd, busyEvents) {
  return busyEvents.some(event => {
    return (slotStart < event.end && slotEnd > event.start);
  });
}

// Функция проверки рабочего времени
function isWorkingHours(date) {
  const hours = date.getHours();
  const day = date.getDay();
  // Исключаем выходные (0 = воскресенье, 6 = суббота)
  if (day === 0 || day === 6) return false;
  return hours >= workStart && hours < workEnd;
}

// Генерация всех возможных слотов
const availableSlots = [];
const now = new Date();
const minBookingTime = new Date(now.getTime() + minLeadTime * 60 * 60 * 1000);

let currentDate = new Date(startDate);

while (currentDate < endDate) {
  // Пропускаем прошедшее время и слоты раньше минимального времени бронирования
  if (currentDate < minBookingTime) {
    currentDate = new Date(currentDate.getTime() + 30 * 60 * 1000);
    continue;
  }

  const slotEnd = new Date(currentDate.getTime() + duration * 60 * 1000);

  // Проверяем, что это рабочее время
  if (isWorkingHours(currentDate)) {
    // Проверяем, что слот не пересекается с занятыми событиями
    if (!isSlotBusy(currentDate, slotEnd, busyEvents)) {
      availableSlots.push({
        date: currentDate.toISOString().split('T')[0],
        time: currentDate.toTimeString().slice(0, 5),
        datetime: currentDate.toISOString(),
        endDatetime: slotEnd.toISOString(),
        displayTime: currentDate.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' }),
        period: currentDate.getHours() < 12 ? 'morning' : currentDate.getHours() < 15 ? 'afternoon' : 'evening'
      });
    }
  }

  currentDate = new Date(currentDate.getTime() + duration * 60 * 1000);
}

// Группируем слоты по датам для удобства
const slotsByDate = availableSlots.reduce((acc, slot) => {
  if (!acc[slot.date]) {
    acc[slot.date] = [];
  }
  acc[slot.date].push(slot);
  return acc;
}, {});

return {
  json: {
    success: true,
    slots: availableSlots,
    slotsByDate: slotsByDate,
    totalSlots: availableSlots.length
  }
};
